-- EffectDieSides2         = 1
-- EffectImplicitTargetA2  = 1    TARGET_UNIT_CASTER -- effect 1 targets the
--                                enemy (6), the heal targets the warrior.
--
-- The description gains "and healing you for $s2% of your maximum health" so
